//! Independent Brainpool vectors, generated by tests/e2e/brainpool_vectors.py.
//! cryptography 50.0.1/OpenSSL derives public points and deterministic DER
//! signatures; hashlib and Python integers derive scalars and RFC 6979 nonces.

use crate::CoseAlg;

/// Public fixed test values; never use these seeds as real credentials.
pub struct Vector {
    /// Algorithm.
    pub alg: CoseAlg,
    /// COSE curve identifier.
    pub crv: i64,
    /// Seed, hexadecimal.
    pub seed: &'static str,
    /// Private scalar, hexadecimal.
    pub scalar: &'static str,
    /// SHAKE256 extra random bits, hexadecimal.
    pub shake: &'static str,
    /// RFC 6979 nonce, hexadecimal.
    pub nonce: &'static str,
    /// Public x, hexadecimal.
    pub x: &'static str,
    /// Public y, hexadecimal.
    pub y: &'static str,
    /// OpenSSL signature over MESSAGE, hexadecimal.
    pub signature: &'static str,
    /// OpenSSL signature made with the wrong hash, hexadecimal.
    pub wrong_hash: &'static str,
}

/// The fixed authenticator data followed by clientDataHash.
pub const MESSAGE: [u8; 69] = {
    let mut message = [0x11; 69];
    let mut i = 37;
    while i < 69 {
        message[i] = 0x22;
        i += 1;
    }
    message
};

